import{_ as s,o as i,c as a,a0 as t}from"./chunks/framework.OED5XGjC.js";const k=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started.md","filePath":"getting-started.md"}'),o={name:"getting-started.md"};function d(n,e,h,r,l,c){return i(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><p>Install the <code>myco</code> CLI, then turn a repo&#39;s <code>project/</code> directory into a work ledger — tasks, issues, proposals, plans, ADRs, handoffs — that lives on its own orphan branch.</p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><p>The <code>myco</code> command is a tamias <code>bins[]</code> pack (<code>libraries/myco</code>) — a generated shim → <code>tamias bin exec</code> → <code>tamias-driver-myco cli</code> → the engine lib. There is no cargo-installed <code>myco</code> binary. With <a href="https://github.com/9aia/tamias" target="_blank" rel="noreferrer">tamias</a> installed:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 9aia:myco@0.1.3</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # org registry (needs TAMIAS_REGISTRY_TOKEN)</span></span></code></pre></div><p>Or the npm launcher — a thin shim that finds the <code>myco</code> bin on PATH and bootstraps tamias + the pack on first run:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 9aia/myco</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># npm ≥ 12 gates git fetches: npm install -g --allow-git=root 9aia/myco</span></span></code></pre></div><p>From a checkout of this repo:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xtask</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pack</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --allow-drivers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./libraries/myco</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xtask</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # tamias-driver-myco → ~/.cargo/bin (dev convenience)</span></span></code></pre></div><p>To also get the <a href="https://github.com/9aia/pavo" target="_blank" rel="noreferrer">pavo</a> view driver (<code>tamias-driver-myco</code>, see below):</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/9aia/myco</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myco-driver</span></span></code></pre></div><h2 id="set-up-a-repo" tabindex="-1">Set up a repo <a class="header-anchor" href="#set-up-a-repo" aria-label="Permalink to &quot;Set up a repo&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> your-repo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">myco</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span></span></code></pre></div><p><code>init</code> creates the orphan <code>project</code> branch, mounts it as a <code>project/</code> worktree, seeds <code>meta.toml</code>, <code>TODO.md</code>, <code>BACKLOG.md</code>, <code>DONE.md</code>, <code>index.md</code> and the item dirs (<code>issues/</code>, <code>proposals/</code>, <code>plans/</code>, <code>adrs/</code>, <code>handoffs/</code>), seeds a commented <code>[[kinds]]</code> prelude into <code>myco.toml</code> at the repo root (only when absent), adds <code>project/</code> to <code>.gitignore</code> on your code branch, and writes a managed <em>Agent awareness</em> block into <code>AGENTS.md</code>. It is idempotent — run it again and a healthy worktree is verified, a damaged one repaired.</p><h2 id="first-items" tabindex="-1">First items <a class="header-anchor" href="#first-items" aria-label="Permalink to &quot;First items&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">myco</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> todo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;ship the thing&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --pri</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> high</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --label</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">myco</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> item</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> T-001</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> in-progress</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">myco</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # ledger digest</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">myco</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> todo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> done</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> T-001</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # the line moves to DONE.md — still browsable</span></span></code></pre></div><p>Every mutating verb is one atomic commit on the <code>project</code> branch — the branch history is the audit trail. <code>--no-commit</code> (or the <code>MYCO_NO_COMMIT</code> env var) opts out.</p><h2 id="the-interactive-board" tabindex="-1">The interactive board <a class="header-anchor" href="#the-interactive-board" aria-label="Permalink to &quot;The interactive board&quot;">​</a></h2><p><code>myco ui</code> opens a full-screen board over <code>TODO.md</code>, <code>BACKLOG.md</code>, and the file-backed kinds (issues, proposals, plans, ADRs) — the human cockpit while agents drive the verbs. Every mutation runs through the same ops the CLI uses, so a keypress that changes the ledger lands as the same atomic commit (<code>--no-commit</code> opts out here too). The board auto-reloads when the ledger changes on disk — an OS filesystem watcher plus a content fingerprint catch other <code>myco</code> invocations, <code>git pull</code>, and hand-edits — no keypress needed; <code>R</code> forces one anyway.</p><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>Tab</code> / <code>Shift-Tab</code>, <code>1</code> / <code>2</code> / <code>3</code>, <code>h</code> / <code>l</code></td><td>cycle / pick TODO / BACKLOG / FILES tabs</td></tr><tr><td><code>j</code> / <code>k</code>, <code>gg</code> / <code>G</code>, <code>{</code>/<code>}</code></td><td>move · ends · section jumps</td></tr><tr><td><code>Enter</code>, <code>→</code></td><td>item preview — <code>j</code>/<code>k</code> scroll, <code>←</code>/esc back</td></tr><tr><td><code>←</code></td><td>back — pops the drill-down stack (esc-like in preview, no-op on the board)</td></tr><tr><td><code>a</code></td><td>add an item (TODO/BACKLOG only)</td></tr><tr><td><code>Space</code> / <code>dd</code>, <code>D</code>, <code>p</code></td><td>done · defer to BACKLOG · promote to TODO (done/undo ask <code>y</code>/<code>n</code>)</td></tr><tr><td><code>u</code> / <code>U</code></td><td>undo / redo ledger commits — <code>U</code> repeats while the redo stack lasts (asks <code>y</code>/<code>n</code>)</td></tr><tr><td><code>Alt+j</code> / <code>Alt+k</code></td><td>reorder among siblings</td></tr><tr><td><code>/</code>, <code>F</code></td><td>live filter · clear it</td></tr><tr><td><code>:</code></td><td>command line — <code>:q</code> <code>:w</code> <code>:e</code> <code>:&lt;id&gt;</code> <code>:set</code></td></tr><tr><td><code>E</code>, <code>R</code>, <code>?</code></td><td><code>$EDITOR</code> · reload · keybind help</td></tr><tr><td><code>q</code>, <code>Ctrl-C</code></td><td>quit</td></tr><tr><td>click, wheel</td><td>select item / tab · scroll</td></tr><tr><td>double-click</td><td>open item preview</td></tr></tbody></table><p><code>--view org-board</code> (or any <code>source = &quot;index&quot;</code> view) swaps the repo ledger for the cross-repo index universe — rows are <code>repo:ID</code> and verbs write the owning repo&#39;s worktree.</p><p>The TUI is a default cargo feature of the engine — the pack build includes it, and since the crates are lib-only there is no <code>--no-default-features</code> install path; feature selection is a pack-build concern.</p><h2 id="visual-views-—-pavo" tabindex="-1">Visual views — pavo <a class="header-anchor" href="#visual-views-—-pavo" aria-label="Permalink to &quot;Visual views — pavo&quot;">​</a></h2><p>For a read-only visual surface (and cross-repo org boards), <a href="https://github.com/9aia/pavo" target="_blank" rel="noreferrer">pavo</a> renders the ledger through <code>tamias-driver-myco</code> (the <code>myco-driver</code> crate in this repo):</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/9aia/myco</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myco-driver</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/9aia/pavo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pavo</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # the host, once</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> your-repo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pavo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> view</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myco:board</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # TODO/BACKLOG tree — also myco:status,</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                         # myco:items, myco:issues, …</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pavo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> open</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myco:board</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # same views in the pavo TUI</span></span></code></pre></div><p>Run <code>pavo</code> inside the repo (or pass <code>--param dir=…/project</code>) so the driver knows which ledger to open. The driver&#39;s reads are view queries; writes ride the same engine verbs — <code>tamias-driver-myco run &lt;verb&gt;</code> (or the driver&#39;s <code>ops</code> manifest / <code>cli.&lt;verb&gt;</code> queries) reaches the full <code>myco</code> surface, commit-per-mutation included. <code>myco ui</code> stays the interactive path.</p><h2 id="agent-self-discovery" tabindex="-1">Agent self-discovery <a class="header-anchor" href="#agent-self-discovery" aria-label="Permalink to &quot;Agent self-discovery&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">myco</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manifest</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # capabilities + protocol version (JSON)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">myco</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schema</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # the file/state spec as JSON Schema</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">myco</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prompt</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # token-sized digest for a context window</span></span></code></pre></div><p>Every verb accepts <code>--json</code>. <code>myco check</code> validates the ledger — file schemas, state machine, index drift — and <code>myco check --fix</code> repairs what it safely can.</p><h2 id="where-next" tabindex="-1">Where next <a class="header-anchor" href="#where-next" aria-label="Permalink to &quot;Where next&quot;">​</a></h2><ul><li><a href="./tutorials/first-item.html">Your first item</a> — a guided walk through a full task lifecycle.</li><li><a href="./how-to/init-repo.html">Set up myco on a repository</a> — discovery, overrides, non-standard layouts.</li><li><a href="./explanation/worktree-model.html">The worktree model</a> — what is actually on disk and why.</li><li><a href="./reference/cli.html">CLI reference</a> — the full verb surface.</li></ul>`,31)])])}const g=s(o,[["render",d]]);export{k as __pageData,g as default};
